NSColor* playerColor(unsigned pk){switch(pk){case 0:return rgb(150,255,240);case 1:return rgb(100,120,255);case 2:return rgb(140,180,255);case 3:return rgb(200,220,255);case 4:return rgb(255,150,60);case 5:return rgb(255,80,30);default:return rgb(255,0,0);}}
// decode_texture(OZJ) flips rows for GPU mesh UVs. AppKit HUD sprites use
